    {"id": "patch_c9bcd0ebf5ab", "mechanism": "Adds reset initialization for m_axis_tdata_reg to 0, ensuring clean state after reset"},
    {"id": "patch_ec27a287b3cc", "mechanism": "Adds reset initialization for m_axis_tdest_reg to 0, ensuring clean state after reset"},
