    {"id": "patch_9d11758b2afe", "mechanism": "Adds reset initialization for temp_m_axis_tkeep_reg to 0, ensuring clean state after reset"},
    {"id": "patch_330141055bc5", "mechanism": "Qualifies frame-based pause condition with !rate_by_frame, preventing incorrect frame pause when rate_by_frame=0"},
    {"id": "patch_177e84f089b9", "mechanism": "Substitutes pause signal with s_axis_tvalid to control backpressure based on input validity"},
    {"id": "patch_4c92a56408a4", "mechanism": "Gates s_axis_tready_reg with rst, preventing ready assertion during reset"}
